import{_ as p,a0 as d,w as o,s as r,I as e,x as a,a1 as n,A as i,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"怎樣用 Bash 編程：語法和工具 | LCTT x X-CMD","titleTemplate":false,"description":"怎樣用 Bash 編程：語法和工具 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣用 Bash 編程：語法和工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣用 Bash 編程：語法和工具 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191021 How to program with Bash- Syntax and tools","title":"怎樣用 Bash 編程：語法和工具","tag":"201911","desc":""},"relativePath":"201911/20191021 How to program with Bash- Syntax and tools.md","filePath":"[post].md"}'),h={name:"201911/20191021 How to program with Bash- Syntax and tools.md"};function u(c,s,m,g,k,b){const t=d("Link");return o(),r("div",null,[s[36]||(s[36]=e("h1",{id:"怎樣用-bash-編程-語法和工具",tabindex:"-1"},[a("怎樣用 Bash 編程：語法和工具 "),e("a",{class:"header-anchor",href:"#怎樣用-bash-編程-語法和工具","aria-label":"Permalink to “怎樣用 Bash 編程：語法和工具”"},"​")],-1)),s[37]||(s[37]=e("blockquote",null,[e("p",null,"讓我們通過本系列文章來學習基本的 Bash 編程語法和工具，以及如何使用變量和控制運算符，這是三篇中的第一篇。")],-1)),s[38]||(s[38]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/201911/08/092559r5wdg0w97dtf350j.jpg",alt:""})],-1)),e("p",null,[s[1]||(s[1]=a("Shell 是操作系統的命令解釋器，其中 Bash 是我最喜歡的。每當用户或者系統管理員將命令輸入系統的時候，Linux 的 shell 解釋器就會把這些命令轉換成操作系統可以理解的形式。而執行結果返回 shell 程序後，它會將結果輸出到 STDOUT（標準輸出），默認情況下，這些結果會",-1)),n(t,{href:"https://opensource.com/article/18/10/linux-data-streams"},{default:i(()=>[...s[0]||(s[0]=[a("顯示在你的終端",-1)])]),_:1}),s[2]||(s[2]=a("。所有我熟悉的 shell 同時也是一門編程語言。",-1))]),s[39]||(s[39]=e("p",null,"Bash 是個功能強大的 shell，包含眾多便捷特性，比如：tab 補全、命令回溯和再編輯、別名等。它的命令列默認編輯模式是 Emacs，但是我最喜歡的 Bash 特性之一是我可以將其更改為 Vi 模式，以使用那些儲存在我肌肉記憶中的的編輯命令。",-1)),e("p",null,[s[4]||(s[4]=a("然而，如果你把 Bash 當作單純的 shell 來用，則無法體驗它的真實能力。我在設計一套包含三卷的 ",-1)),n(t,{href:"http://www.both.org/?page_id=1183"},{default:i(()=>[...s[3]||(s[3]=[a("Linux 自學課程",-1)])]),_:1}),s[5]||(s[5]=a("時（這個系列的文章正是基於此課程），瞭解到許多 Bash 的知識，這些是我在過去 20 年的 Linux 工作經驗中所沒有掌握的，其中的一些知識就是關於 Bash 的編程用法。不得不説，Bash 是一門強大的編程語言，是一個能夠同時用於命令列和 shell 腳本的完美設計。",-1))]),s[40]||(s[40]=e("p",null,[a("本系列文章將要探討如何使用 Bash 作為命令列界面（CLI）編程語言。第一篇文章簡單介紹 Bash 命令列編程、變量以及控制運算符。其他文章會討論諸如：Bash 文件的類型；字符串、數字和一些邏輯運算符，它們能夠提供代碼執行流程中的邏輯控制；不同類型的 shell 擴展；通過 "),e("code",null,"for"),a("、"),e("code",null,"while"),a(" 和 "),e("code",null,"until"),a(" 來控制循環操作。")],-1)),s[41]||(s[41]=e("h3",{id:"shell",tabindex:"-1"},[a("Shell "),e("a",{class:"header-anchor",href:"#shell","aria-label":"Permalink to “Shell”"},"​")],-1)),e("p",null,[s[8]||(s[8]=a("Bash 是 Bourne Again Shell 的縮寫，因為 Bash shell 是 ",-1)),n(t,{href:"https://opensource.com/19/9/command-line-heroes-bash"},{default:i(()=>[...s[6]||(s[6]=[a("基於",-1)])]),_:1}),s[9]||(s[9]=a(" 更早的 Bourne shell，後者是 Steven Bourne 在 1977 年開發的。另外還有很多",-1)),n(t,{href:"https://en.wikipedia.org/wiki/Comparison_of_command_shells"},{default:i(()=>[...s[7]||(s[7]=[a("其他的 shell",-1)])]),_:1}),s[10]||(s[10]=a(" 可以使用，但下面四個是我經常見到的：",-1))]),s[42]||(s[42]=l('<ul><li><code>csh</code>：C shell 適合那些習慣了 C 語言語法的開發者。</li><li><code>ksh</code>：Korn shell，由 David Korn 開發，在 Unix 用户中更流行。</li><li><code>tcsh</code>：一個 csh 的變種，增加了一些易用性。</li><li><code>zsh</code>：Z shell，集成了許多其他流行 shell 的特性。</li></ul><p>所有 shell 都有內置命令，用以補充或替代核心工具集。打開 shell 的 man 説明頁，找到“BUILT-INS”那一段，可以查看都有哪些內置命令。</p><p>每種 shell 都有它自己的特性和語法風格。我用過 csh、ksh 和 zsh，但我還是更喜歡 Bash。你可以多試幾個，尋找更適合你的 shell，儘管這可能需要花些功夫。但幸運的是，切換不同 shell 很簡單。</p><p>所有這些 shell 既是編程語言又是命令解釋器。下面我們來快速瀏覽一下 Bash 中集成的編程結構和工具。</p><h3 id="作為編程語言的-bash" tabindex="-1">作為編程語言的 Bash <a class="header-anchor" href="#作為編程語言的-bash" aria-label="Permalink to “作為編程語言的 Bash”">​</a></h3><p>大多數場景下，系統管理員都會使用 Bash 來發送簡單明瞭的命令。但 Bash 不僅可以輸入單條命令，很多系統管理員可以編寫簡單的命令列程序來執行一系列任務，這些程序可以作為通用工具，能節省時間和精力。</p><p>編寫 CLI 程序的目的是要提高效率（做一個“懶惰的”系統管理員）。在 CLI 程序中，你可以用特定順序列出若干命令，逐條執行。這樣你就不用盯着顯示屏，等待一條命令執行完，再輸入另一條，省下來的時間就可以去做其他事情了。</p><h3 id="什麼是-程序" tabindex="-1">什麼是“程序”？ <a class="header-anchor" href="#什麼是-程序" aria-label="Permalink to “什麼是“程序”？”">​</a></h3>',8)),e("p",null,[s[14]||(s[14]=a("自由在線計算機詞典（",-1)),n(t,{href:"http://foldoc.org/program"},{default:i(()=>[...s[11]||(s[11]=[a("FOLDOC",-1)])]),_:1}),s[15]||(s[15]=a("）對於程序的定義是：“由計算機執行的指令，而不是運行它們的物理硬件。”普林斯頓大學的 ",-1)),n(t,{href:"https://wordnet.princeton.edu/"},{default:i(()=>[...s[12]||(s[12]=[a("WordNet",-1)])]),_:1}),s[16]||(s[16]=a(" 將程序定義為：“……計算機可以理解並執行的一系列指令……”",-1)),n(t,{href:"https://en.wikipedia.org/wiki/Computer_program"},{default:i(()=>[...s[13]||(s[13]=[a("維基百科",-1)])]),_:1}),s[17]||(s[17]=a("上也有一條不錯的關於計算機程序的條目。",-1))]),s[43]||(s[43]=l(`<p>總結下，程序由一條或多條指令組成，目的是完成一個具體的相關任務。對於系統管理員而言，一段程序通常由一系列的 shell 命令構成。Linux 下所有的 shell （至少我所熟知的）都有基本的編程功能，Bash 作為大多數 linux 發行版的默認 shell，也不例外。</p><p>本系列用 Bash 舉例（因為它無處不在），假如你使用一個不同的 shell 也沒關係，儘管結構和語法有所不同，但編程思想是相通的。有些 shell 支持某種特性而其他 shell 則不支持，但它們都提供編程功能。Shell 程序可以被存在一個文件中被反覆使用，或者在需要的時候才創建它們。</p><h3 id="簡單-cli-程序" tabindex="-1">簡單 CLI 程序 <a class="header-anchor" href="#簡單-cli-程序" aria-label="Permalink to “簡單 CLI 程序”">​</a></h3><p>最簡單的命令列程序只有一或兩條語句，它們可能相關，也可能無關，在按回車鍵之前被輸入到命令列。程序中的第二條語句（如果有的話）可能取決於第一條語句的操作，但也不是必須的。</p><p>這裏需要特別講解一個標點符號。當你在命令列輸入一條命令，按下回車鍵的時候，其實在命令的末尾有一個隱含的分號（<code>;</code>）。當一段 CLI shell 程序在命令列中被串起來作為單行指令使用時，必須使用分號來終結每個語句並將其與下一條語句分開。但 CLI shell 程序中的最後一條語句可以使用顯式或隱式的分號。</p><h3 id="一些基本語法" tabindex="-1">一些基本語法 <a class="header-anchor" href="#一些基本語法" aria-label="Permalink to “一些基本語法”">​</a></h3><p>下面的例子會闡明這一語法規則。這段程序由單條命令組成，還有一個顯式的終止符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ echo &quot;Hello world.&quot; ;</span></span>
<span class="line"><span>Hello world.</span></span></code></pre></div><p>看起來不像一個程序，但它確是我學習每個新編程語言時寫下的第一個程序。不同語言可能語法不同，但輸出結果是一樣的。</p><p>讓我們擴展一下這段微不足道卻又無所不在的代碼。你的結果可能與我的有所不同，因為我的家目錄有點亂，而你可能是在 GUI 桌面中第一次登錄賬號。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ echo &quot;My home directory.&quot; ; ls ;</span></span>
<span class="line"><span>My home directory.</span></span>
<span class="line"><span>chapter25   TestFile1.Linux  dmesg2.txt  Downloads  newfile.txt  softlink1  testdir6</span></span>
<span class="line"><span>chapter26   TestFile1.mac    dmesg3.txt  file005    Pictures     Templates  testdir</span></span>
<span class="line"><span>TestFile1      Desktop       dmesg.txt   link3      Public       testdir    Videos</span></span>
<span class="line"><span>TestFile1.dos  dmesg1.txt    Documents   Music      random.txt   testdir1</span></span></code></pre></div><p>現在是不是更明顯了。結果是相關的，但是兩條語句彼此獨立。你可能注意到我喜歡在分號前後多輸入一個空格，這樣會讓代碼的可讀性更好。讓我們再運行一遍這段程序，這次不要帶結尾的分號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ echo &quot;My home directory.&quot; ; ls</span></span></code></pre></div><p>輸出結果沒有區別。</p><h3 id="關於變量" tabindex="-1">關於變量 <a class="header-anchor" href="#關於變量" aria-label="Permalink to “關於變量”">​</a></h3><p>像所有其他編程語言一樣，Bash 支持變量。變量是個象徵性的名字，它指向內存中的某個位置，那裏存着對應的值。變量的值是可以改變的，所以它叫“變~量”。</p>`,16)),e("p",null,[s[19]||(s[19]=a("Bash 不像 C 之類的語言，需要強制指定變量類型，比如：整型、浮點型或字符型。在 Bash 中，所有變量都是字符串。整數型的變量可以被用於整數運算，這是 Bash 唯一能夠處理的數學類型。更復雜的運算則需要藉助 ",-1)),n(t,{href:"https://www.gnu.org/software/bc/manual/html_mono/bc.html"},{default:i(()=>[...s[18]||(s[18]=[a("bc",-1)])]),_:1}),s[20]||(s[20]=a(" 這樣的命令，可以被用在命令列編程或者腳本中。",-1))]),s[44]||(s[44]=l(`<p>變量的值是被預先分配好的，這些值可以用在命令列編程或者腳本中。可以通過變量名字給其賦值，但是不能使用 <code>$</code> 符開頭。比如，<code>VAR=10</code> 這樣會把 <code>VAR</code> 的值設為 <code>10</code>。要打印變量的值，你可以使用語句 <code>echo $VAR</code>。變量名必須以文本（即非數字）開始。</p><p>Bash 會保存已經定義好的變量，直到它們被取消掉。</p><p>下面這個例子，在變量被賦值前，它的值是空（<code>null</code>）。然後給它賦值並打印出來，檢驗一下。你可以在同一行 CLI 程序裏完成它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ echo $MyVar ; MyVar=&quot;Hello World&quot; ; echo $MyVar ;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hello World</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p><em>注意：變量賦值的語法非常嚴格，等號（<code>=</code>）兩邊不能有空格。</em></p><p>那個空行表明了 <code>MyVar</code> 的初始值為空。變量的賦值和改值方法都一樣，這個例子展示了原始值和新的值。</p><p>正如之前説的，Bash 支持整數運算，當你想計算一個數組中的某個元素的位置，或者做些簡單的算術運算，這還是挺有幫助的。然而，這種方法並不適合科學計算，或是某些需要小數運算的場景，比如財務統計。這些場景有其它更好的工具可以應對。</p><p>下面是個簡單的算術題：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ Var1=&quot;7&quot; ; Var2=&quot;9&quot; ; echo &quot;Result = $((Var1*Var2))&quot;</span></span>
<span class="line"><span>Result = 63</span></span></code></pre></div><p>好像沒啥問題，但如果運算結果是浮點數會發生什麼呢？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ Var1=&quot;7&quot; ; Var2=&quot;9&quot; ; echo &quot;Result = $((Var1/Var2))&quot;</span></span>
<span class="line"><span>Result = 0</span></span>
<span class="line"><span>[student@studentvm1 ~]$ Var1=&quot;7&quot; ; Var2=&quot;9&quot; ; echo &quot;Result = $((Var2/Var1))&quot;</span></span>
<span class="line"><span>Result = 1</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p>結果會被取整。請注意運算被包含在 <code>echo</code> 語句之中，其實計算在 echo 命令結束前就已經完成了，原因是 Bash 的內部優先級。想要了解詳情的話，可以在 Bash 的 man 頁面中搜索 “precedence”。</p><h3 id="控制運算符" tabindex="-1">控制運算符 <a class="header-anchor" href="#控制運算符" aria-label="Permalink to “控制運算符”">​</a></h3><p>Shell 的控制運算符是一種語法運算符，可以輕鬆地創建一些有趣的命令列程序。在命令列上按順序將幾個命令串在一起，就變成了最簡單的 CLI 程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command1 ; command2 ; command3 ; command4 ; . . . ; etc. ;</span></span></code></pre></div><p>只要不出錯，這些命令都能順利執行。但假如出錯了怎麼辦？你可以預設好應對出錯的辦法，這就要用到 Bash 內置的控制運算符， <code>&amp;&amp;</code> 和 <code>||</code>。這兩種運算符提供了流程控制功能，使你能改變代碼執行的順序。分號也可以被看做是一種 Bash 運算符，預示着新一行的開始。</p><p><code>&amp;&amp;</code> 運算符提供瞭如下簡單邏輯，“如果 command1 執行成功，那麼接着執行 command2。如果 command1 失敗，就跳過 command2。”語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command1 &amp;&amp; command2</span></span></code></pre></div><p>現在，讓我們用命令來創建一個新的目錄，如果成功的話，就把它切換為當前目錄。確保你的家目錄（<code>~</code>）是當前目錄，先嚐試在 <code>/root</code> 目錄下創建，你應該沒有權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ Dir=/root/testdir ; mkdir $Dir/ &amp;&amp; cd $Dir</span></span>
<span class="line"><span>mkdir: cannot create directory &#39;/root/testdir/&#39;: Permission denied</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p>上面的報錯信息是由 <code>mkdir</code> 命令拋出的，因為創建目錄失敗了。<code>&amp;&amp;</code> 運算符收到了非零的返回碼，所以 <code>cd</code> 命令就被跳過，前者阻止後者繼續運行，因為創建目錄失敗了。這種控制流程可以阻止後面的錯誤累積，避免引發更嚴重的問題。是時候講點更復雜的邏輯了。</p><p>當一段程序的返回碼大於零時，使用 <code>||</code> 運算符可以讓你在後面接着執行另一段程序。簡單語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command1 || command2</span></span></code></pre></div><p>解讀一下，“假如 command1 失敗，執行 command2”。隱藏的邏輯是，如果 command1 成功，跳過 command2。下面實踐一下，仍然是創建新目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ Dir=/root/testdir ; mkdir $Dir || echo &quot;$Dir was not created.&quot;</span></span>
<span class="line"><span>mkdir: cannot create directory &#39;/root/testdir&#39;: Permission denied</span></span>
<span class="line"><span>/root/testdir was not created.</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p>正如預期，因為目錄無法創建，第一條命令失敗了，於是第二條命令被執行。</p><p>把 <code>&amp;&amp;</code> 和 <code>||</code> 兩種運算符結合起來才能發揮它們的最大功效。請看下面例子中的流程控制方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>前置 commands ; command1 &amp;&amp; command2 || command3 ; 跟隨 commands</span></span></code></pre></div><p>語法解釋：“假如 command1 退出時返回碼為零，就執行 command2，否則執行 command3。”用具體代碼試試：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ Dir=/root/testdir ; mkdir $Dir &amp;&amp; cd $Dir || echo &quot;$Dir was not created.&quot;</span></span>
<span class="line"><span>mkdir: cannot create directory &#39;/root/testdir&#39;: Permission denied</span></span>
<span class="line"><span>/root/testdir was not created.</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p>現在我們再試一次，用你的家目錄替換 <code>/root</code> 目錄，你將會有權限創建這個目錄了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ Dir=~/testdir ; mkdir $Dir &amp;&amp; cd $Dir || echo &quot;$Dir was not created.&quot;</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>像 <code>command1 &amp;&amp; command2</code> 這樣的控制語句能夠運行的原因是，每條命令執行完畢時都會給 shell 發送一個返回碼，用來表示它執行成功與否。默認情況下，返回碼為 <code>0</code> 表示成功，其他任何正值表示失敗。一些系統管理員使用的工具用值為 <code>1</code> 的返回碼來表示失敗，但其他很多程序使用別的數字來表示失敗。</p><p>Bash 的內置變量 <code>$?</code> 可以顯示上一條命令的返回碼，可以在腳本或者命令列中非常方便地檢查它。要查看返回碼，讓我們從運行一條簡單的命令開始，返回碼的結果總是上一條命令給出的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ ll ; echo &quot;RC = $?&quot;</span></span>
<span class="line"><span>total 1264</span></span>
<span class="line"><span>drwxrwxr-x  2 student student   4096 Mar  2 08:21 chapter25</span></span>
<span class="line"><span>drwxrwxr-x  2 student student   4096 Mar 21 15:27 chapter26</span></span>
<span class="line"><span>-rwxr-xr-x  1 student student     92 Mar 20 15:53 TestFile1</span></span>
<span class="line"><span>drwxrwxr-x. 2 student student 663552 Feb 21 14:12 testdir</span></span>
<span class="line"><span>drwxr-xr-x. 2 student student   4096 Dec 22 13:15 Videos</span></span>
<span class="line"><span>RC = 0</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>在這個例子中，返回碼為零，意味着命令執行成功了。現在對 root 的家目錄測試一下，你應該沒有權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ ll /root ; echo &quot;RC = $?&quot;</span></span>
<span class="line"><span>ls: cannot open directory &#39;/root&#39;: Permission denied</span></span>
<span class="line"><span>RC = 2</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>本例中返回碼是 <code>2</code>，表明非 root 用户沒有權限進入這個目錄。你可以利用這些返回碼，用控制運算符來改變程序執行的順序。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>本文將 Bash 看作一門編程語言，並從這個視角介紹了它的簡單語法和基礎工具。我們學習瞭如何將數據輸出到 STDOUT，怎樣使用變量和控制運算符。在本系列的下一篇文章中，將會重點介紹能夠控制指令執行流程的邏輯運算符。</p><hr>`,41)),e("p",null,[s[22]||(s[22]=a("via: ",-1)),n(t,{href:"https://opensource.com/article/19/10/programming-bash-part-1"},{default:i(()=>[...s[21]||(s[21]=[a("https://opensource.com/article/19/10/programming-bash-part-1",-1)])]),_:1})]),e("p",null,[s[27]||(s[27]=a("作者：",-1)),n(t,{href:"https://opensource.com/users/dboth"},{default:i(()=>[...s[23]||(s[23]=[a("David Both",-1)])]),_:1}),s[28]||(s[28]=a(" 選題：",-1)),n(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[24]||(s[24]=[a("lujun9972",-1)])]),_:1}),s[29]||(s[29]=a(" 譯者：",-1)),n(t,{href:"https://github.com/jdh8383"},{default:i(()=>[...s[25]||(s[25]=[a("jdh8383",-1)])]),_:1}),s[30]||(s[30]=a(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:i(()=>[...s[26]||(s[26]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[33]||(s[33]=a("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[31]||(s[31]=[a("LCTT",-1)])]),_:1}),s[34]||(s[34]=a(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:i(()=>[...s[32]||(s[32]=[a("Linux中國",-1)])]),_:1}),s[35]||(s[35]=a(" 榮譽推出",-1))])])}const y=p(h,[["render",u]]);export{C as __pageData,y as default};
